1	"use client";
2	
3	import { useMemo, useState, useTransition } from "react";
4	import { useRouter } from "next/navigation";
5	import { saveGameConfig } from "@/lib/actions-game-config";
6	import type { ConfigField, FamilySchema } from "@/lib/game-config";
7	import { SearchableSelect } from "@/components/customer/SearchableSelect";
8	
9	type Values = Record<string, string | number | boolean>;
10	
11	/**
12	 * Dynamic per-game settings form. Renders the family schema (grouped fields, the
13	 * right widget per type) plus a variant/loader picker, and persists via
14	 * `saveGameConfig` — which validates, stores the values and enqueues a
15	 * GAME_CONFIG job to apply them.
16	 */
17	export function GameSettings({
18	  serverId,
19	  schema,
20	  variant: initialVariant,
21	  values: initialValues,
22	  disabled,
23	}: {
24	  serverId: string;
25	  schema: FamilySchema;
26	  variant: string;
27	  values: Values;
28	  disabled?: boolean;
29	}) {
30	  const router = useRouter();
31	  const [variant, setVariant] = useState(initialVariant);
32	  const [values, setValues] = useState<Values>(initialValues);
33	  const [error, setError] = useState<string | null>(null);
34	  const [saved, setSaved] = useState(false);
35	  const [pending, start] = useTransition();
36	
37	  // Fields grouped by their `group` heading, preserving declaration order.
38	  const groups = useMemo(() => {
39	    const map = new Map<string, ConfigField[]>();
40	    for (const f of schema.fields) {
41	      if (!map.has(f.group)) map.set(f.group, []);
42	      map.get(f.group)!.push(f);
43	    }
44	    return [...map.entries()];
45	  }, [schema]);
46	
47	  function set(key: string, value: string | number | boolean) {
48	    setValues((v) => ({ ...v, [key]: value }));
49	    setSaved(false);
50	  }
51	
52	  function save() {
53	    start(async () => {
54	      setError(null);
55	      setSaved(false);
56	      const res = await saveGameConfig(serverId, variant, values);
57	      if (res?.error) setError(res.error);
58	      else {
59	        setSaved(true);
60	        router.refresh();
61	      }
62	    });
63	  }
64	
65	  const activeVariant = schema.variants.find((v) => v.id === variant);
66	
67	  return (
68	    <div className="card">
69	      <div className="flex flex-wrap items-start justify-between gap-4">
70	        <div>
71	          <h2 className="font-semibold">Game settings</h2>
72	          <p className="mt-1 max-w-xl text-sm text-slate-400">
73	            Configure your {schema.label} server. Changes are queued and applied to the server —
74	            some settings only take effect after the next restart.
75	          </p>
76	        </div>
77	        <button className="btn-primary" disabled={pending || disabled} onClick={save}>
78	          {pending ? "Saving…" : "Save & apply"}
79	        </button>
80	      </div>
81	
82	      {/* Variant / loader picker */}
83	      <div className="mt-5">
84	        <label className="block text-sm">
85	          <span className="mb-1.5 block font-medium">Server type</span>
86	          <select
87	            className="input"
88	            value={variant}
89	            disabled={pending || disabled}
90	            onChange={(e) => {
91	              setVariant(e.target.value);
92	              setSaved(false);
93	            }}
94	          >
95	            {schema.variants.map((v) => (
96	              <option key={v.id} value={v.id}>
97	                {v.label}
98	              </option>
99	            ))}
100	          </select>
101	        </label>
102	        {activeVariant?.description && (
103	          <p className="mt-1.5 text-xs text-slate-500">{activeVariant.description}</p>
104	        )}
105	      </div>
106	
107	      {groups.map(([group, fields]) => (
108	        <div key={group} className="mt-6">
109	          <p className="section-label">{group}</p>
110	          <div className="mt-3 grid gap-4 sm:grid-cols-2">
111	            {fields.map((f) => (
112	              <Field
113	                key={f.key}
114	                field={f}
115	                value={values[f.key]}
116	                disabled={pending || disabled}
117	                onChange={(val) => set(f.key, val)}
118	              />
119	            ))}
120	          </div>
121	        </div>
122	      ))}
123	
124	      <div className="mt-5 flex flex-wrap items-center gap-3">
125	        <button className="btn-primary" disabled={pending || disabled} onClick={save}>
126	          {pending ? "Saving…" : "Save & apply"}
127	        </button>
128	        {saved && !error && <span className="text-sm text-emerald-400">Settings queued for apply.</span>}
129	        {error && <span className="text-sm text-red-400">{error}</span>}
130	      </div>
131	    </div>
132	  );
133	}
134	
135	function Field({
136	  field,
137	  value,
138	  disabled,
139	  onChange,
140	}: {
141	  field: ConfigField;
142	  value: string | number | boolean | undefined;
143	  disabled?: boolean;
144	  onChange: (v: string | number | boolean) => void;
145	}) {
146	  const isMissing = !!field.required && String(value ?? field.default ?? "").trim() === "";
147	  const labelRow = (
148	    <span className="mb-1.5 flex items-baseline justify-between gap-2">
149	      <span className="font-medium">{field.label}</span>
150	      {field.required ? (
151	        <span
152	          className={`text-[10px] font-semibold uppercase tracking-wide ${isMissing ? "text-red-300" : "text-emerald-400"}`}
153	        >
154	          {isMissing ? "Required — server won't start without this" : "Required ✓"}
155	        </span>
156	      ) : (
157	        field.phase === "deploy" && (
158	          <span className="text-[10px] uppercase tracking-wide text-amber-300/80">restart</span>
159	        )
160	      )}
161	    </span>
162	  );
163	
164	  if (field.type === "bool") {
165	    const on = value === true;
166	    return (
167	      <div className="flex items-center justify-between gap-4 rounded-xl border border-white/[0.06] bg-navy-950/40 px-3.5 py-3">
168	        <span className="text-sm">
169	          <span className="font-medium">{field.label}</span>
170	          {field.help && <span className="mt-0.5 block text-xs text-slate-500">{field.help}</span>}
171	        </span>
172	        <button
173	          type="button"
174	          role="switch"
175	          aria-checked={on}
176	          disabled={disabled}
177	          onClick={() => onChange(!on)}
178	          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
179	            on ? "bg-brand-500" : "bg-white/15"
180	          } ${disabled ? "opacity-60" : ""}`}
181	        >
182	          <span
183	            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
184	              on ? "translate-x-5" : "translate-x-0.5"
185	            }`}
186	          />
187	        </button>
188	      </div>
189	    );
190	  }
191	
192	  return (
193	    <label className="block text-sm">
194	      {labelRow}
195	      {field.type === "enum" && field.searchable ? (
196	        <SearchableSelect
197	          options={field.options ?? []}
198	          value={String(value ?? field.default)}
199	          disabled={disabled}
200	          onChange={onChange}
201	          placeholder={`Search ${field.label.toLowerCase()}…`}
202	        />
203	      ) : field.type === "enum" ? (
204	        <select
205	          className="input"
206	          value={String(value ?? field.default)}
207	          disabled={disabled}
208	          onChange={(e) => onChange(e.target.value)}
209	        >
210	          {field.options?.map((o) => (
211	            <option key={o.value} value={o.value}>
212	              {o.label}
213	            </option>
214	          ))}
215	        </select>
216	      ) : field.type === "int" ? (
217	        <input
218	          className="input"
219	          type="number"
220	          value={value === undefined || value === null ? Number(field.default) : Number(value)}
221	          min={field.min}
222	          max={field.max}
223	          step={1}
224	          disabled={disabled}
225	          onChange={(e) => onChange(e.target.value === "" ? "" as any : Number(e.target.value))}
226	        />
227	      ) : (
228	        <input
229	          className={`input ${isMissing ? "border-red-400/60 focus:border-red-400" : ""}`}
230	          type="text"
231	          value={String(value ?? field.default)}
232	          maxLength={256}
233	          disabled={disabled}
234	          aria-invalid={isMissing}
235	          onChange={(e) => onChange(e.target.value)}
236	        />
237	      )}
238	      {field.help && (
239	        <span className={`mt-1 block text-xs ${isMissing ? "text-red-300" : "text-slate-500"}`}>{field.help}</span>
240	      )}
241	    </label>
242	  );
243	}
