1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import { connectionTarget, serverRootPassword } from "../lib/sftp";
4	import {
5	  familyFor,
6	  schemaFor,
7	  validateConfig,
8	  GAME_CONFIG_VERSION,
9	} from "../lib/game-config";
10	import { controlSpec } from "../lib/game-control";
11	import { Client, type ClientChannel, type SFTPWrapper } from "ssh2";
12	import type { Job } from "@prisma/client";
13	import { readFileSync } from "node:fs";
14	import { join } from "node:path";
15	
16	/**
17	 * GAME_CONFIG handler — apply a game server's customization (variant + settings).
18	 *
19	 * `worker/index.ts` owns the job loop and its `handlers` map; wire this in there:
20	 *   GAME_CONFIG: gameConfigApply,
21	 *
22	 * Ownership + validation happen at enqueue time (lib/actions-game-config.ts), so
23	 * this handler trusts `Server.gameVariant` / `Server.gameConfig`.
24	 *
25	 * TWO PATHS:
26	 *  - DEFAULT (simulation): records an "applied" marker on `Server.gameConfig` and
27	 *    notifies the user. No SSH, no VM mutation. This runs under SANDBOX and, in
28	 *    production, for any family not yet verified (see below).
29	 *
30	 *  - REAL: actually pushes the settings to the live game server over SSH. Runs
31	 *    per-family (see `REAL_APPLY_FAMILIES`) rather than one blanket switch — a
32	 *    family's real path is deliberately non-destructive (read-modify-write for
33	 *    key=value files, or — for images like Palworld's that regenerate their
34	 *    config from env vars on every boot — a full container recreation with
35	 *    rollback on failure; never clobbers a config it can't find/parse) and
36	 *    fully wrapped in try/catch so a failure notifies the user but never
37	 *    crashes the worker. `ENABLE_REAL_GAMECFG=1` additionally force-enables
38	 *    every family at once, for whenever the rest have been confirmed too.
39	 *
40	 * Enable a family's real path only once its config paths / service names / apply
41	 * function have been confirmed for the actual game-server image — see
42	 * `REAL_APPLY_FAMILIES`'s own comment for what "confirmed" means in practice.
43	 */
44	
45	/** Force-enables every family's real path at once — set only once ALL of them
46	 *  have been individually confirmed, not as a way to unblock just one. */
47	const REAL_APPLY_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMECFG === "1";
48	
49	/**
50	 * Families whose real-apply path has been individually built AND verified
51	 * against the actual production image/container, so it's safe to run even
52	 * while `ENABLE_REAL_GAMECFG` stays off for everyone else.
53	 *
54	 * "verified" here means: confirmed live, end-to-end, against a real running
55	 * container — not just "the code looks right". `palworld` was added
56	 * 2026-09-05 after the previous version of `applyPalworld` was found to
57	 * silently regenerate-then-lose its own writes (see that function's comment);
58	 * the replacement was verified by actually recreating a live container with
59	 * an updated setting and reading the resulting config back off disk.
60	 *
61	 * `minecraft` added 2026-09-06: verified against a real throwaway server on
62	 * node-2 (provisioned, applied `difficulty` + `online-mode` via
63	 * `applyRealConfig` directly, read `/opt/mc/server.properties` back off disk
64	 * and confirmed both values, then destroyed the VM). The path-detection
65	 * TODO on `applyMinecraft` is resolved for the current image: the host-side
66	 * bind mount (`/opt/mc` -> `/data`) puts server.properties somewhere
67	 * `remoteLocate`'s `find` over /opt already reaches. One real, non-blocking
68	 * gap found: `mcrcon` is not installed on the image, so today every setting
69	 * falls back to "restart to apply" — correctly reported as such, never
70	 * silently claimed live — rather than the live-RCON push `tryMinecraftRcon`
71	 * would otherwise attempt for difficulty/whitelist/etc.
72	 *
73	 * `rust` added 2026-09-06 by the whole-catalog integrity sweep, after
74	 * `applyRust` was found to be writing a `server.cfg` that (a) does not exist on
75	 * this image and (b) would have been ignored even if it did — see that
76	 * function's own comment for the two live proofs. The replacement recreates the
77	 * container from `RUST_SERVER_*` env vars, and was verified by reading **every
78	 * field in the Rust schema back off the live running game** via its own RCON,
79	 * not off a config file: `server.hostname: "NXEON SWEEP RUST"`,
80	 * `server.maxplayers: "42"`, `server.worldsize: "4000"`, `server.pve: "True"`,
81	 * and `server.seed: "12345"` still at its old value — proving untouched
82	 * settings survive the recreate. Independently corroborated by the server's own
83	 * boot log, whose occlusion grid went 1750 -> 2000 (worldsize/2) across the
84	 * change. One real caveat, reported to the customer in the apply's own notes
85	 * rather than hidden: Rust reloads its entire map on restart, so an apply takes
86	 * that server offline for several minutes — far longer than Palworld's seconds.
87	 *
88	 * `valheim` added 2026-09-06 by the same sweep. Its old implementation was the
89	 * worst-behaved of the three pre-written ones — it wrote a launch-args file
90	 * nothing read and returned `ok: true`, so the customer was told "Game settings
91	 * applied" while the server was untouched. The replacement recreates the
92	 * container from `WORLD_NAME` + `SERVER_ARGS`, and was verified against the
93	 * REAL RUNNING PROCESS's argv (`-world NxeonSweepWorld … -preset hard`, from
94	 * `-world Nxeon` and no preset) plus the server genuinely creating the new
95	 * world on disk (`NxeonSweepWorld.fwl`) while keeping the old one — exactly what
96	 * the apply's own note promises the customer.
97	 */
98	const REAL_APPLY_FAMILIES = new Set<string>(["palworld", "minecraft", "rust", "valheim"]);
99	
100	function familyRealApplyEnabled(family: string): boolean {
101	  return REAL_APPLY_ENABLED || REAL_APPLY_FAMILIES.has(family);
102	}
103	
104	const CONNECT_TIMEOUT_MS = 15_000;
105	const EXEC_TIMEOUT_MS = 30_000;
106	
107	async function notify(userId: string, title: string, body?: string, href?: string) {
108	  try {
109	    await db.notification.create({ data: { userId, title, body, href } });
110	  } catch (e) {
111	    console.error("[game-config] notify failed", e);
112	  }
113	}
114	
115	export async function gameConfigApply(job: Job): Promise<void> {
116	  const serverId = job.serverId;
117	  if (!serverId) throw new Error("game config: job has no serverId");
118	
119	  const server = await db.server.findUnique({
120	    where: { id: serverId },
121	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
122	  });
123	  if (!server) throw new Error(`Server ${serverId} not found`);
124	
125	  const family = familyFor(server);
126	  const schema = schemaFor(family);
127	  if (!family || !schema) {
128	    throw new Error(`game config: ${server.hostname} is not a customizable game server`);
129	  }
130	
131	  const variant = server.gameVariant ?? schema.defaultVariant;
132	  const realApply = familyRealApplyEnabled(family);
133	
134	  // -------------------------------------------------------------------------
135	  // Simulation is a SANDBOX affordance and MUST NEVER run in production.
136	  //
137	  // Until 2026-07-26 it did: production has no ENABLE_REAL_GAMECFG, so every real
138	  // customer request fell through to the block below, stamped an `_appliedAt`
139	  // marker, and notified them "Game settings applied on <hostname>" — with the
140	  // "(sandbox)" suffix suppressed, because SANDBOX is false on production. So the
141	  // customer changed their difficulty or slot count, was told it was applied, and
142	  // nothing on the server had changed.
143	  //
144	  // Identical in kind to the SSL bug fixed the same day, where production wrote a
145	  // certificate row as ACTIVE with an invented expiry while no certbot had run:
146	  // the system asserting an outcome it never performed. A change we did not apply
147	  // is a FAILURE, and it must say so loudly enough that an operator notices the
148	  // flag is missing.
149	  // -------------------------------------------------------------------------
150	  if (!realApply && !SANDBOX) {
151	    throw new Error(
152	      "Game settings could not be applied: real application is switched off on this " +
153	        "server (ENABLE_REAL_GAMECFG is not set), so nothing was written to the game " +
154	        "server and your settings are NOT in effect. Please contact support."
155	    );
156	  }
157	
158	  if (!realApply) {
159	    const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
160	    const marker = {
161	      _appliedVariant: variant,
162	      _appliedAt: new Date().toISOString(),
163	      _configVersion: GAME_CONFIG_VERSION,
164	      _sandbox: SANDBOX,
165	    };
166	
167	    await db.server.update({
168	      where: { id: server.id },
169	      data: { gameConfig: { ...existing, ...marker } as any },
170	    });
171	
172	    await notify(
173	      server.userId,
174	      `Game settings applied on ${server.hostname}`,
175	      `${schema.label} (${variant}) settings were applied${SANDBOX ? " (sandbox)" : ""}.`,
176	      `/dashboard/servers/${server.id}?tab=game settings`
177	    );
178	    return;
179	  }
180	
181	  // -------------------------------------------------------------------------
182	  // REAL PATH — gated behind ENABLE_REAL_GAMECFG. Everything below is wrapped so
183	  // a failure notifies the user but never throws out of the handler.
184	  // -------------------------------------------------------------------------
185	  const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
186	  const valid = validateConfig(family, existing);
187	  // `existing` also holds the `_`-prefixed markers; validateConfig drops unknown
188	  // keys, so `values` is exactly the schema fields keyed on the game's own keys.
189	  const values = valid.ok ? valid.values : {};
190	
191	  let outcome: ApplyOutcome = { ok: false, applied: [], notes: [] };
192	  try {
193	    outcome = await applyRealConfig(server, family, values);
194	  } catch (e) {
195	    const msg = e instanceof Error ? e.message : String(e);
196	    console.error(`[game-config] real apply failed on ${server.hostname}:`, e);
197	    outcome = { ok: false, applied: [], notes: [`Apply failed: ${msg}`] };
198	  }
199	
200	  // Always record the applied-marker (even on partial/soft failure) so the portal
201	  // reflects the attempt, and note whether the real push succeeded.
202	  const marker = {
203	    _appliedVariant: variant,
204	    _appliedAt: new Date().toISOString(),
205	    _configVersion: GAME_CONFIG_VERSION,
206	    _sandbox: SANDBOX,
207	    _real: true,
208	    _realOk: outcome.ok,
209	  };
210	  try {
211	    await db.server.update({
212	      where: { id: server.id },
213	      data: { gameConfig: { ...existing, ...marker } as any },
214	    });
215	  } catch (e) {
216	    console.error("[game-config] marker update failed", e);
217	  }
218	
219	  const detail = [...outcome.applied, ...outcome.notes].join(" ");
220	  await notify(
221	    server.userId,
222	    outcome.ok
223	      ? `Game settings applied on ${server.hostname}`
224	      : `Game settings partially applied on ${server.hostname}`,
225	    `${schema.label} (${variant}) — ${detail || "no changes were made."}`,
226	    `/dashboard/servers/${server.id}?tab=game settings`
227	  );
228	}
229	
230	// ===========================================================================
231	// Real apply — per-family rendering + SSH transport
232	// ===========================================================================
233	
234	type Values = Record<string, string | number | boolean>;
235	type ApplyOutcome = { ok: boolean; applied: string[]; notes: string[] };
236	
237	/** The minimal Server shape the real path needs to open an SSH connection. */
238	export type SshServer = {
239	  id: string;
240	  rootPassword: string | null;
241	  rootPasswordEnc?: string | null;
242	  sshPort: number | null;
243	  dedicatedIp?: { address: string } | null;
244	  node?: { publicIp: string } | null;
245	  gameVariant?: string | null;
246	};
247	
248	/**
249	 * Connect to the game-server VM (host/port derived exactly like the file manager,
250	 * user "root", password `rootPassword`), run `fn`, and always close the session.
251	 */
252	function withSsh<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
253	  return new Promise((resolve, reject) => {
254	    const target = connectionTarget(server as any);
255	    if (!target) {
256	      reject(new Error("server is not reachable yet — connection details are pending"));
257	      return;
258	    }
259	    const password = serverRootPassword(server);
260	    if (!password) {
261	      reject(new Error("server has no root password set"));
262	      return;
263	    }
264	
265	    const conn = new Client();
266	    let settled = false;
267	    const finish = (err: Error | null, val?: T) => {
268	      if (settled) return;
269	      settled = true;
270	      try {
271	        conn.end();
272	      } catch {
273	        /* best-effort */
274	      }
275	      if (err) reject(err);
276	      else resolve(val as T);
277	    };
278	
279	    conn.on("ready", () => {
280	      conn.sftp((err, sftp) => {
281	        if (err) return finish(err);
282	        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
283	      });
284	    });
285	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
286	    conn.connect({
287	      host: target.host,
288	      port: target.port,
289	      username: "root",
290	      password,
291	      readyTimeout: CONNECT_TIMEOUT_MS,
292	    });
293	  });
294	}
295	
296	/** Read a remote text file, or null if it does not exist. */
297	function sftpRead(sftp: SFTPWrapper, path: string): Promise<string | null> {
298	  return new Promise((resolve, reject) => {
299	    sftp.readFile(path, (err, data) => {
300	      if (err) {
301	        // ENOENT / no such file → null; anything else is a real error.
302	        const code = (err as NodeJS.ErrnoException).code;
303	        if (code === "ENOENT" || code === "No such file" || /no such file/i.test(err.message)) {
304	          return resolve(null);
305	        }
306	        return reject(err);
307	      }
308	      resolve(data.toString("utf8"));
309	    });
310	  });
311	}
312	
313	/** Write a remote text file (overwrites). */
314	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
315	  return new Promise((resolve, reject) => {
316	    sftp.writeFile(path, Buffer.from(content, "utf8"), (err) => (err ? reject(err) : resolve()));
317	  });
318	}
319	
320	/** Write a remote binary file (overwrites) — same as sftpWrite but skips utf8 re-encoding. */
321	function sftpWriteBinary(sftp: SFTPWrapper, path: string, content: Buffer): Promise<void> {
322	  return new Promise((resolve, reject) => {
323	    sftp.writeFile(path, content, (err) => (err ? reject(err) : resolve()));
324	  });
325	}
326	
327	/** Run a remote shell command; resolves with stdout/stderr/exit-code (never rejects on non-zero). */
328	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
329	  return new Promise((resolve, reject) => {
330	    conn.exec(cmd, (err, stream: ClientChannel) => {
331	      if (err) return reject(err);
332	      let stdout = "";
333	      let stderr = "";
334	      const timer = setTimeout(() => {
335	        try {
336	          stream.close();
337	        } catch {
338	          /* ignore */
339	        }
340	      }, EXEC_TIMEOUT_MS);
341	      stream
342	        .on("close", (code: number) => {
343	          clearTimeout(timer);
344	          resolve({ code: code ?? 0, stdout, stderr });
345	        })
346	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
347	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
348	    });
349	  });
350	}
