352	/**
353	 * Locate the first existing path: try explicit candidates via `test -f`, then a
354	 * bounded `find` over `findRoots` for `findName`. Returns the path or null.
355	 * Non-destructive — only reads.
356	 */
357	async function remoteLocate(
358	  conn: Client,
359	  candidates: string[],
360	  findRoots: string[],
361	  findName: string
362	): Promise<string | null> {
363	  const testExpr = candidates.map((p) => `if [ -f '${shq(p)}' ]; then echo '${shq(p)}'; exit 0; fi;`).join(" ");
364	  const findExpr = findRoots.length
365	    ? `for r in ${findRoots.map((r) => `'${shq(r)}'`).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name '${shq(findName)}' 2>/dev/null | head -1; done | head -1`
366	    : "true";
367	  const { stdout } = await execRemote(conn, `${testExpr} ${findExpr}`);
368	  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.length > 0);
369	  return hit ?? null;
370	}
