377	/**
378	 * The systemd unit that supervises this family's game container, or null if the
379	 * guest has none.
380	 *
381	 * Every game family's setup script is rewritten at PROVISION time by
382	 * worker/index.ts's `wrapDockerGameService()` into `docker create` plus a
383	 * `<hint>.service` unit (`ExecStart=docker start -a <container>`,
384	 * `Restart=always`, `RestartSec=5`) — and that wrapper deliberately STRIPS
385	 * docker's own `--restart` policy, in its own words because "leaving both in
386	 * place makes the two supervisors fight over a crash-looping process". So on
387	 * every game server this platform provisions, systemd — not docker — owns the
388	 * container's lifecycle, and any apply path that stops or recreates a container
389	 * MUST go through it.
390	 *
391	 * Returns null when no unit resolves (a server provisioned before that wrapper
392	 * shipped, or a setup script that didn't match its `docker run -d --name X`
393	 * shape). There, docker's own restart policy is the only supervisor there is
394	 * and has to be preserved rather than replaced.
395	 *
396	 * The hints come from `lib/game-control.ts`'s per-family `controlSpec` — the
397	 * same list `worker/game-control.ts`'s power buttons resolve against, and the
398	 * same list `wrapDockerGameService` names the unit from ([0]) — so this can
399	 * never drift from the unit that actually got installed.
400	 */
401	async function resolveGameUnit(conn: Client, family: string): Promise<string | null> {
402	  const hints = controlSpec(family)?.serviceHints ?? [];
403	  if (!hints.length) return null;
404	  const probe = hints
405	    .map((h) => `systemctl cat '${shq(h)}.service' >/dev/null 2>&1 && { echo '${shq(h)}.service'; exit 0; };`)
406	    .join(" ");
407	  const { stdout } = await execRemote(conn, probe);
408	  const hit = stdout
409	    .split(/\r?\n/)
410	    .map((s) => s.trim())
411	    .find((s) => s.endsWith(".service"));
412	  return hit ?? null;
413	}
