478	
479	/** Update `key value` (whitespace-separated) lines in place; append missing keys. */
480	function updateConvars(content: string, updates: Record<string, string>): string {
481	  const lines = content.split(/\r?\n/);
482	  const seen = new Set<string>();
483	  for (let i = 0; i < lines.length; i++) {
484	    const t = lines[i].trim();
485	    if (!t || t.startsWith("//") || t.startsWith("#")) continue;
486	    const sp = t.search(/\s/);
487	    const key = sp < 0 ? t : t.slice(0, sp);
488	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
489	      lines[i] = `${key} ${updates[key]}`;
490	      seen.add(key);
491	    }
492	  }
493	  for (const k of Object.keys(updates)) {
494	    if (!seen.has(k)) lines.push(`${k} ${updates[k]}`);
495	  }
496	  return lines.join("\n");
497	}
