505	
506	/**
507	 * Read a container's current environment as a map.
508	 *
509	 * Recreating a container means re-supplying its WHOLE environment, not just the
510	 * keys being changed: the images this is used for get most of their defaults
511	 * from their own Dockerfile `ENV`s, and dropping those would silently reset
512	 * settings the customer never touched. `PATH` is excluded — the image always
513	 * injects a correct one, and carrying ours over would be wrong.
514	 */
515	async function readContainerEnv(conn: Client, container: string): Promise<Map<string, string> | null> {
516	  const inspect = await execRemote(conn, `docker inspect ${container} --format '{{json .Config.Env}}'`);
517	  if (inspect.code !== 0) return null;
518	  let envArr: string[];
519	  try {
520	    envArr = JSON.parse(inspect.stdout.trim());
521	  } catch {
522	    return null;
523	  }
524	  const envMap = new Map<string, string>();
525	  for (const entry of envArr) {
526	    const idx = entry.indexOf("=");
527	    if (idx < 0) continue;
528	    envMap.set(entry.slice(0, idx), entry.slice(idx + 1));
529	  }
530	  envMap.delete("PATH");
531	  return envMap;
532	}
533	
534	/** The exact image reference (repo:tag) a running container was created from. */
535	async function readContainerImage(conn: Client, container: string): Promise<string | null> {
536	  const res = await execRemote(conn, `docker inspect ${container} --format '{{.Config.Image}}'`);
537	  if (res.code !== 0) return null;
538	  const image = res.stdout.trim();
539	  return image || null;
540	}
