542	/** Write an env map to a root-only `--env-file` on the guest. */
543	async function writeEnvFile(conn: Client, sftp: SFTPWrapper, path: string, envMap: Map<string, string>): Promise<void> {
544	  const content = Array.from(envMap.entries()).map(([k, v]) => `${k}=${v.replace(/\r?\n/g, " ")}`).join("\n") + "\n";
545	  await sftpWrite(sftp, path, content);
546	  await execRemote(conn, `chmod 600 '${shq(path)}'`);
547	}
