849	/** Replace `<flag> <value>` in an argument string, or append the pair if absent. */
850	function upsertArg(args: string, flag: string, value: string): string {
851	  const esc = flag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
852	  const re = new RegExp(`(^|\\s)${esc}\\s+\\S+`);
853	  return re.test(args) ? args.replace(re, `$1${flag} ${value}`) : `${args} ${flag} ${value}`.trim();
854	}
855	
856	/** Strip `<flag> <value>` from an argument string entirely, if present. */
857	function removeArg(args: string, flag: string): string {
858	  const esc = flag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
859	  const re = new RegExp(`(^|\\s)${esc}\\s+\\S+`);
860	  return args.replace(re, "").trim();
861	}
862	
863	/** Replace `+convar <value>` in a Rust startup-argument string, or append it. */
864	function upsertConvarArg(args: string, convar: string, value: string): string {
865	  return upsertArg(args, `+${convar}`, value);
866	}
