896	  if (!envMap) {
897	    return { ok: false, applied: [], notes: [`Could not find the "${RUST_CONTAINER}" container — nothing was changed.`] };
898	  }
899	
900	  const applied: string[] = [];
901	  const notes: string[] = [];
902	  for (const [key, val] of Object.entries(v)) {
903	    if (val == null) continue;
904	    const env = RUST_ENV_MAP[key];
905	    if (env) {
906	      envMap.set(env, String(val));
