910	      // through verbatim ahead of the generated pairs, so it is the image's own
911	      // escape hatch for any convar it has no variable for.
912	      const args = envMap.get("RUST_SERVER_STARTUP_ARGUMENTS") ?? "-batchmode -load -nographics +server.secure 1";
