917	  if (applied.length === 0) {
918	    return { ok: true, applied: [], notes: ["No changes to apply."] };
919	  }
920	
921	  await writeEnvFile(conn, sftp, "/root/rust.env", envMap);
922	
923	  const res = await recreateGameContainer(conn, {
924	    family: "rust",
925	    container: RUST_CONTAINER,
926	    runFlags: RUST_RUN_FLAGS,
927	    image: RUST_IMAGE,
928	  });
