1243	const PALWORLD_CONTAINER = "palworld";
1244	
1245	/** Schema field key → Palworld env var name + how to format the value. */
1246	const PALWORLD_ENV_MAP: Record<string, { env: string; format: (v: string | number | boolean) => string }> = {
1247	  difficulty: { env: "DIFFICULTY", format: (v) => String(v) },
1248	  "death-penalty": { env: "DEATH_PENALTY", format: (v) => String(v) },
1249	  pvp: { env: "IS_PVP", format: (v) => (bool(v) === "true" ? "True" : "False") },
1250	  "exp-rate": {
1251	    env: "EXP_RATE",
1252	    format: (v) => {
1253	      const n = Number(v);
1254	      return Number.isFinite(n) ? n.toFixed(6) : String(v);
1255	    },
1256	  },
1257	  "player-caps": { env: "PLAYERS", format: (v) => String(v) },
1258	  "pal-box-import": { env: "ALLOW_GLOBAL_PALBOX_IMPORT", format: (v) => (bool(v) === "true" ? "True" : "False") },
1259	  "pal-box-export": { env: "ALLOW_GLOBAL_PALBOX_EXPORT", format: (v) => (bool(v) === "true" ? "True" : "False") },
1260	  // The image's own official escape hatch (see start.sh): when true, boot skips
1261	  // regenerating PalWorldSettings.ini entirely (only copies a default template
1262	  // if the file is completely empty) — the only way to give a customer a
1263	  // config file that genuinely survives restarts. Found live 2026-09-05.
1264	  "raw-config-mode": { env: "DISABLE_GENERATE_SETTINGS", format: (v) => (bool(v) === "true" ? "True" : "False") },
1265	};
1266	
1267	async function applyPalworld(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
1268	  const envMap = await readContainerEnv(conn, PALWORLD_CONTAINER);
1269	  if (!envMap) {
1270	    return { ok: false, applied: [], notes: [`Could not find the "${PALWORLD_CONTAINER}" container — nothing was changed.`] };
1271	  }
1272	
1273	  const applied: string[] = [];
1274	  for (const [key, val] of Object.entries(v)) {
1275	    const mapping = PALWORLD_ENV_MAP[key];
1276	    if (!mapping || val == null) continue;
1277	    envMap.set(mapping.env, mapping.format(val));
1278	    applied.push(key);
1279	  }
1280	  if (applied.length === 0) {
1281	    return { ok: true, applied: [], notes: ["No changes to apply."] };
1282	  }
1283	
1284	  await writeEnvFile(conn, sftp, "/root/palworld.env", envMap);
1285	
1286	  // Ports + volume exactly as prisma/catalog.ts provisions them, except RCON,
1287	  // which is bound to loopback rather than 0.0.0.0 — the platform's own RCON
1288	  // tunnels to 127.0.0.1 over SSH, so nothing needs it published.
1289	  const res = await recreateGameContainer(conn, {
1290	    family: "palworld",
1291	    container: PALWORLD_CONTAINER,
1292	    runFlags: "-p 8211:8211/udp -p 127.0.0.1:25575:25575/tcp -v /opt/palworld:/palworld --env-file /root/palworld.env",
1293	    image: "thijsvanloef/palworld-server-docker",
1294	  });
1295	  if (!res.ok) return { ok: false, applied: [], notes: [res.note] };
1296	
1297	  return {
1298	    ok: true,
1299	    applied: [`Applied ${applied.length} setting(s): ${applied.join(", ")}.`],
1300	    notes: ["Your server restarted briefly to apply these — any connected players were disconnected and can rejoin now."],
1301	  };
1302	}
